export const basicsChallenge: ModuleChallenge = {
  title: "Seconds to a clock",
  statement: "A stopwatch app stores elapsed time as a whole number of seconds. Show it as hours, minutes and seconds in the form H:MM:SS, where the hours have no leading zero and the minutes and seconds always have two digits. Hours do not wrap at 24.",
  inputFormat: "One integer s, the number of seconds.",
  outputFormat: "One line in the form H:MM:SS.",
  constraints: ["0 <= s <= 1000000000"],
  exampleCount: 2,
  explanations: ["3661 seconds is 1 hour, 1 minute and 1 second.", "59 seconds is under a minute, so the hours and minutes are zero."],
  reference: "s = int(input())\nprint(f\"{s // 3600}:{s % 3600 // 60:02d}:{s % 60:02d}\")\n",
  tests: [
    { input: "3661\n", output: "1:01:01\n" },
    { input: "59\n", output: "0:00:59\n" },
    { input: "0\n", output: "0:00:00\n" },
    { input: "60\n", output: "0:01:00\n" },
    { input: "3600\n", output: "1:00:00\n" },
    { input: "86399\n", output: "23:59:59\n" },
    { input: "90061\n", output: "25:01:01\n" },
    { input: "1000000000\n", output: "277777:46:40\n" },
  ],
};

