export const functionsChallenge: ModuleChallenge = {
  title: "Is it a palindrome?",
  statement: "A phrase is a palindrome if it reads the same forwards and backwards when you ignore everything that is not a letter or a digit and ignore upper and lower case. Decide whether the given phrase is one.",
  inputFormat: "One line of text, which may contain spaces and punctuation.",
  outputFormat: "YES if the phrase is a palindrome, otherwise NO.",
  constraints: ["1 <= length of the line <= 1000", "the line contains at least one letter or digit"],
  exampleCount: 2,
  explanations: ["Ignoring spaces, punctuation and case it reads amanaplanacanalpanama in both directions.", "hello reversed is olleh, which is different."],
  reference: "s = [c.lower() for c in input() if c.isalnum()]\nprint('YES' if s == s[::-1] else 'NO')\n",
  tests: [
    { input: "A man, a plan, a canal: Panama\n", output: "YES\n" },
    { input: "hello\n", output: "NO\n" },
    { input: "Racecar\n", output: "YES\n" },
    { input: "No lemon, no melon\n", output: "YES\n" },
    { input: "ab\n", output: "NO\n" },
    { input: "x\n", output: "YES\n" },
    { input: "12321\n", output: "YES\n" },
    { input: "Was it a car or a cat I saw?\n", output: "YES\n" },
    { input: "race a car\n", output: "NO\n" },
  ],
};

