  inputFormat: "One line of lower-case words separated by single spaces.",
  outputFormat: "The word, a space, and how many times it appears.",
  constraints: ["1 <= number of words <= 10000", "every word has between 1 and 20 letters"],
  exampleCount: 2,
  explanations: ["the appears 3 times, more than any other word.", "Both b and a appear twice, and a comes first alphabetically."],
  reference: "w = input().split()\nfrom collections import Counter\nc = Counter(w)\nbest = max(c.values())\nprint(min(k for k, v in c.items() if v == best), best)\n",
